import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { NUM, quoteV1, paymentBound, requiredReserveAt, unpackPlan, type KeeperWork } from './planner';
import { V2 } from '../sim/fund';

/** This fixture is generated by forge test --match-path test/PolicyModelParity.t.sol, never by this model. */
interface Step {
  action: string;
  deposited: string; collected: string; claimed: string; mintCost: string; mintedBacking: string;
  redeemed: string; reward: string; measuredGas: string; shapeUnits: string; listedPrizes: string;
  reconciledDraws: string; processedDraws: string; balance: string; creatorCredit: string; creatorRevenueBps: string; required: string;
  target: string; maxReward: string; owed: string; ownerProceeds: string;
  activeCount: string; refundCredit: string; enabled: boolean; have: number[]; mintFee: string;
  version: number; baseFee: string; gasPrice: string; deliveredBacking: string; ownerAccrued: string;
  livePrices: string[]; listedBacking: string; drawPrice: string;
}

describe('independent economic replay of the fork lifecycle', () => {
  it('matches every pool, fee, reserve, payment, FWA-proceeds and backing step under V1 and V2', () => {
    const rows = Object.values(JSON.parse(readFileSync('test/fixtures/keeper-policy-money-path.json', 'utf8'))) as Step[];
    expect(rows.length).toBeGreaterThan(15);
    let balance = 0n;
    let backing = 0n;
    let credit = 0n;
    let fwaProceeds = 0n;
    let previous: Step | undefined;
    const paidVersions = new Set<number>();
    for (const step of rows) {
      const b = (k: keyof Step) => BigInt(step[k] as string);
      if (b('collected')) {
        const rate = previous ? BigInt(previous.creatorRevenueBps) : b('creatorRevenueBps');
        credit += b('collected') * rate / 10000n;
      }
      balance += b('deposited') + b('collected') + b('redeemed') - b('mintCost') - b('reward');
      backing += b('mintedBacking') - b('redeemed') - b('deliveredBacking');
      fwaProceeds += b('ownerAccrued') - b('collected');
      credit = b('claimed') >= credit ? 0n : credit - b('claimed');
      balance -= b('claimed');
      expect(balance, `${step.action}: liquid ETH`).toBe(b('balance'));
      expect(backing, `${step.action}: real FWA listed backing`).toBe(b('listedBacking'));
      expect(credit, `${step.action}: protected creator credit`).toBe(b('creatorCredit'));
      expect(balance).toBeGreaterThanOrEqual(credit);
      expect(fwaProceeds, `${step.action}: owner proceeds still at FWA`).toBe(b('ownerProceeds'));
      const maximum = b('maxReward');
      const need = step.enabled
        ? requiredReserveAt(unpackPlan(b('target')), step.have, b('mintFee'), Number(step.owed), maximum, b('baseFee'))
        : requiredReserveAt(unpackPlan(b('target')), step.have, b('mintFee'), Number(step.owed), maximum, b('baseFee'), false);
      expect(need, `${step.action}: reserve`).toBe(b('required'));
      const prices = step.livePrices.map(BigInt);
      const weights = prices.map((p) => NUM / p);
      const w = weights.reduce((a, x) => a + x, 0n);
      const wp = prices.reduce((a, p, i) => a + p * weights[i], 0n);
      const drawPrice = w === 0n ? 0n : (wp / w) * 10500n / 10000n;
      expect(drawPrice, `${step.action}: fixed listing prices/FWA quote`).toBe(b('drawPrice'));
      if (b('reward') > 0n) {
        const work: KeeperWork = { measuredGas: b('measuredGas'), gasPrice: b('gasPrice'), baseFee: b('baseFee'),
          reconciledDraws: b('reconciledDraws'), listedShapeUnits: b('shapeUnits'), listedPrizes: b('listedPrizes'), processedDraws: b('processedDraws') };
        const quote = step.version === 1 ? quoteV1(work) : V2.reward(work);
        const ceiling = paymentBound(work, maximum);
        const reward = quote < ceiling ? quote : ceiling;
        expect(reward, `${step.action}: actual measured work compensation`).toBe(b('reward'));
        expect(reward).toBeLessThanOrEqual(maximum);
        paidVersions.add(step.version);
      }
      expect(b('baseFee')).toBe(500_000_000n);
      expect(b('gasPrice')).toBe(550_000_000n);
      previous = step;
    }
    expect(paidVersions).toEqual(new Set([1, 2]));
    expect(balance).toBe(0n);
    expect(backing).toBe(0n);
    expect(fwaProceeds).toBe(0n);
    expect(BigInt(rows.at(-1)!.refundCredit)).toBeGreaterThan(0n);
  });
});
